		donpcevent "#arn_timer_70::OnStop";
		donpcevent "alloff#70::OnEnable";
		donpcevent "Lv70 Waiting Room::OnStart";
		end;
	} else {
		emotion ET_HUK;
		mes "[Staff]";
		mes "Wow! You have renewed the record!";
		mes "What a great job!";
		next;
